  for (const bundle of matchingBundles) {
    // Idempotency: insert into dedup ledger; if already exists, skip.
    // Uses ON CONFLICT on (bundle_id, order_external_id) unique constraint.
    await sql`
      INSERT INTO bundle_order_increments (bundle_id, order_external_id)
      VALUES (${bundle.id}, ${BigInt(orderExternalId)})
      ON CONFLICT (bundle_id, order_external_id) DO NOTHING
    `;

    // Only increment if the dedup row was freshly inserted.
    // We check rows affected by attempting a conditional update:
    // increment purchase_count only when a dedup row exists with matching
    // created_at = now() (i.e., just inserted).
    // Instead, use a safer pattern: increment unconditionally guarded by
    // the unique dedup row — we must do this atomically in a transaction.
    await sql.begin(async (tx) => {
      // Check if the increment row was JUST inserted (no prior row).
      const [dedupRow] = await tx<{ id: string; created_at: string }[]>`
        SELECT id, created_at
        FROM bundle_order_increments
        WHERE bundle_id = ${bundle.id}
          AND order_external_id = ${BigInt(orderExternalId)}
      `;
      if (!dedupRow) return; // Shouldn't happen, but guard anyway.

      // Try to increment: only applies if this is the first insert.
      // The dedup table guarantees we've only inserted once.
      // To avoid double-increment: track whether we should increment
      // by attempting an "insert-or-nothing" and checking if rows affected > 0.
      // Since ON CONFLICT DO NOTHING returns 0 rows on conflict, we check
      // by re-inserting a sentinel and inspecting result count.
      // Simpler: store a flag in bundle_order_increments or accept the
      // insert-then-increment pattern with the unique constraint as the guard.
      // The correct pattern: increment happened exactly when the dedup row was
      // NEW. We'll use a different approach: keep a separate counter column
      // and do UPDATE ... WHERE NOT EXISTS the duplicate.
      await tx`
        UPDATE bundles
        SET purchase_count = purchase_count + 1,
            updated_at = now()
        WHERE id = ${bundle.id}
          AND (
            SELECT COUNT(*) FROM bundle_order_increments
            WHERE bundle_id = ${bundle.id}
              AND order_external_id = ${BigInt(orderExternalId)}
          ) = 1
      `;
    });

    console.log(
      { topic: "orders/create", bundleId: bundle.id, orderId: orderExternalId },
      "Bundle purchase count incremented"
    );
  }
},

// ─── products/update ───────────────────────────────────────────────────────
// Refresh availability flags on bundle_items when a product's status or
// variant availability changes.
"products/update": async (
  payload: ProductsUpdatePayload,
  _req: Request
): Promise<void> => {
  // Signal fields from payloadBindings:
  //   product external id ← payload.id
  //   product status ← payload.status
  //   variant availability list ← payload.variants
  const productExternalId = payload.id;
  const productStatus = payload.status;
  const variants = payload.variants ?? [];

  console.log(
    { topic: "products/update", productId: productExternalId, status: productStatus },
    "Refreshing bundle item availability"
  );

  // A product is considered available when status === "active".
  // If the product is not active, mark all bundle items for this product as unavailable.
  const isProductActive = productStatus === "active";

  // Additionally check if any variant has inventory available.
  // A variant is available if inventory_quantity > 0 OR inventory_policy === "continue".
  const anyVariantAvailable = variants.some(
    (v) =>
      v.inventory_quantity > 0 || v.inventory_policy === "continue"
  );

  // Available = product is active AND at least one variant is available
  // (or variants array is empty, which could mean product has no variants yet).
  const itemAvailable =
    isProductActive && (variants.length === 0 || anyVariantAvailable);

  // Update all bundle_items matching this product external id.
  // Idempotent: always overwrite with the latest state.
  await sql`
    UPDATE bundle_items
    SET available = ${itemAvailable}
    WHERE product_external_id = ${BigInt(productExternalId)}
  `;
